function paragraphs(t){return String(t).split(/\n\s*\n/).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('');}
function example(e,l,id){return '<figure class="outbound-example" aria-labelledby="'+id+'"><figcaption><h3 id="'+id+'">'+esc(e.heading)+'</h3><p class="example-label">'+esc(e.label)+'</p></figcaption><dl><dt>'+q(l,['Observed context','Contexto observado','Context observat','Contexte observé'])+'</dt><dd>'+esc(e.fact)+'</dd><dt>'+q(l,['Unknowns','Incógnitas','Incògnites','Inconnues'])+'</dt><dd>'+esc(e.unknown)+'</dd></dl><div class="message-analysis"><div><blockquote>'+paragraphs(e.message)+'</blockquote>'+(e.follow?'<div class="short-followup"><h4>'+q(l,['Brief follow-up if there is no reply','Seguimiento breve si no responde','Seguiment breu si no respon','Courte relance sans réponse'])+'</h4><blockquote>'+paragraphs(e.follow)+'</blockquote></div>':'')+'</div><aside class="annotation-notes" aria-label="'+q(l,['Message annotations','Anotaciones del mensaje','Anotacions del missatge','Annotations du message'])+'"><h4>'+q(l,['Why these choices','Por qué se elige así','Per què es tria així','Pourquoi ces choix'])+'</h4><ol>'+e.notes.map(n=>'<li><span aria-hidden="true">→ </span>'+esc(n)+'</li>').join('')+'</ol></aside></div></figure>';}
